import * as React from "react";
import { CommonProps } from "../utility/commonProps";
export interface CollapseProps extends React.ComponentPropsWithoutRef<"div">, CommonProps {
    /**
     * If the component is collapsed.
     *
     * @default false
     */
    isOpen?: boolean;
}
/**
 * A utility component that is used to put long sections of information under a block that users can expand or collapse.
 *
 * - {@link https://livingdesign.walmart.com/utilities/collapse/react/ React documentation}
 *
 * ### Is open
 *
 * The Collapse accepts an optional `isOpen` prop which controls the appearance of it's `children`.
 *
 * ```tsx
 * import * as React from "react";
 * import { Button, Collapse } from "@walmart-web/livingdesign-components";
 *
 * export default () => {
 *   const [state, setState] = React.useState(false)
 *   return (
 *     <div>
 *       <Button onChange={() => setState(!state)}>
 *         {state ? "Open" : "Collapse"}
 *       </Button>
 *       <Collapse isOpen={state}>
 *         <p>
 *           Capitalize on low hanging fruit to identify a
 *           ballpark value added activity to beta test.
 *           Override the digital divide with additional
 *           clickthroughs from DevOps. Nanotechnology
 *           immersion along the information highway will close
 *           the loop on focusing solely on the bottom line.
 *         </p>
 *       </Collapse>
 *     </div>
 *   );
 * }
 * ```
 */
export declare const Collapse: React.FunctionComponent<CollapseProps>;
